import sqlite3, json

conn = sqlite3.connect('world.db')
cur = conn.cursor()

# Fix ALL flights - remove invalid cabin classes and fix null times
rows = cur.execute("SELECT flight_id, dates_json, departure_time, arrival_time FROM flights").fetchall()
invalid_cabins = {'premium_economy', 'first', 'premium'}

for row in rows:
    flight_id, dates_json_str, dep_time, arr_time = row
    dates = json.loads(dates_json_str) if dates_json_str else {}
    changed = False

    for date_key, date_data in dates.items():
        # Remove invalid cabin classes from prices
        if 'prices' in date_data:
            for bad in invalid_cabins:
                if bad in date_data['prices']:
                    del date_data['prices'][bad]
                    changed = True
        # Fix invalid statuses (e.g. 'active' -> 'available')
        if date_data.get('status') not in ('available', 'cancelled', 'delayed', 'on time', 'flying', 'landed'):
            date_data['status'] = 'available'
            changed = True

    updates = []
    vals = []
    if changed:
        updates.append("dates_json=?")
        vals.append(json.dumps(dates))
    if dep_time is None:
        updates.append("departure_time=?")
        vals.append('09:00')
    if arr_time is None:
        updates.append("arrival_time=?")
        vals.append('10:30')

    if updates:
        vals.append(flight_id)
        cur.execute(f"UPDATE flights SET {', '.join(updates)} WHERE flight_id=?", vals)

# Fix ALL passengers missing dob
rows = cur.execute("SELECT booking_id, passengers_json FROM flight_bookings").fetchall()
for row in rows:
    booking_id, pj = row
    passengers = json.loads(pj) if pj else []
    changed = False
    for p in passengers:
        if 'dob' not in p:
            p['dob'] = p.get('date_of_birth', '1990-01-01')
            changed = True
    if changed:
        cur.execute("UPDATE flight_bookings SET passengers_json=? WHERE booking_id=?", [json.dumps(passengers), booking_id])

conn.commit()
conn.close()
print("All DB records patched successfully")
EOF
